function rx_cube = simulate_moving_target_echo(params, t, R0, v, attenuation)
%SIMULATE_MOVING_TARGET_ECHO Generate a chirp-train echo for one moving point target.
%
%   rx_cube = SIMULATE_MOVING_TARGET_ECHO(params, t, R0, v, attenuation) returns an
%   Ns x Nchirps matrix, one column per chirp, using the stop-and-hop approximation
%   (decision D6): range is held constant WITHIN each chirp (tau computed once per
%   chirp) but advances chirp-to-chirp as R(m) = R0 + v*(m-1)*T_CRI. Each column is
%   generated by calling simulate_target_echo.m UNMODIFIED (same function used in
%   Phase 1/2), so the only new logic here is the slow-time range update loop.
%
%   Inputs:
%       params      - struct from get_radar_params()
%       t           - 1 x Ns fast-time sample vector [s] (from generate_chirp)
%       R0          - target range at the start of the frame [m]
%       v           - target radial velocity [m/s] (positive = increasing range /
%                     receding, by this project's fixed convention -- see
%                     docs/parameter_reference.md)
%       attenuation - scalar linear amplitude attenuation factor
%   Outputs:
%       rx_cube - Ns x Nchirps complex matrix (fast-time along rows, per the axis
%                 convention in docs/architecture.md §5)

    Ns = numel(t);
    Nchirps = params.frame.Nchirps;
    T_CRI = params.wave.T_CRI;

    rx_cube = zeros(Ns, Nchirps);
    for m = 1:Nchirps
        R_m = R0 + v*(m-1)*T_CRI;
        rx_row = simulate_target_echo(params, t, R_m, attenuation);  % 1 x Ns
        rx_cube(:, m) = rx_row.';
    end

end
